  ('discounts', 1, 'Discounts', 'economics', 'EGP', 'measured', 'Σ discount_total (line discounts at merchandise grains), non-excluded orders created in the period', NULL, NULL, '["week","drop","offer","location","product","variant","size","category"]', 'lower_better', 'drop_day', NULL, '["fact_order","fact_order_line"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
