  ('net_sales_attributed', 1, 'Net sales', 'economics', 'EGP', 'measured', 'gross_sales − discounts − reversals_attributed (reversals attributed to order week)', NULL, NULL, '["week","drop","offer","location","product","variant","size","category","governorate"]', 'higher_better', 'drop_day', NULL, '["fact_order","fact_order_line","fact_reversal"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
  ('ordered_revenue', 1, 'Ordered revenue', 'economics', 'EGP', 'measured', 'Σ total of non-cancelled, non-excluded orders created in the period', NULL, NULL, '["week","drop","offer","location"]', 'higher_better', 'drop_day', 'A claim on money, not money: COD orders are uncollected until delivered.', '["fact_order"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
  ('delivered_revenue', 1, 'Delivered revenue', 'economics', 'EGP', 'measured', 'Σ (total − shipping_charged − tax) over delivered orders created in the period', NULL, NULL, '["week","drop","offer","location","product","variant","size","category","governorate"]', 'higher_better', 'drop_day', 'Right-censored: orders in transit are not delivered yet; coverage states the resolved share.', '["fact_order"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
  ('net_to_delivered_bridge', 1, 'Not yet delivered, shipping and tax', 'economics', 'EGP', 'measured', 'net_sales_attributed − delivered_revenue: undelivered orders plus pass-through shipping and tax', NULL, NULL, '["week"]', 'neutral', 'none', 'Bridges the waterfall''s net sales to the delivered basis gross profit is computed on.', '["fact_order","fact_order_line","fact_reversal"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
