  ('ad_spend', 1, 'Ad spend', 'economics', 'EGP', 'measured', 'Σ fact_ad_daily.spend, all platforms', NULL, NULL, '["week","drop","offer","platform","campaign","adset","ad","concept","angle","hook_type","format","creator","product"]', 'neutral', 'none', 'Billed spend. The one platform figure allowed into Shopify-denominated ratios, because it is money paid, not a platform claim. At product grain: spend on ads promoting the product.', '["fact_ad_daily"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
  ('fulfilment_cost_outbound', 1, 'Fulfilment (outbound)', 'economics', 'EGP', 'modelled', 'courier rate by zone × shipped orders created in the period', NULL, NULL, '["week","drop","governorate","courier_zone"]', 'lower_better', 'drop_day', 'Modelled from the rate card until courier invoices are loaded; that change is a new definition version.', '["fact_order","dim_geo"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
  ('cod_collection_fees', 1, 'COD collection fees', 'economics', 'EGP', 'modelled', 'COD fee rate × collected value on delivered COD orders', NULL, NULL, '["week","drop"]', 'lower_better', 'drop_day', 'Charged on collected value only. The fee rate is a stated assumption until confirmed against courier statements.', '["fact_order"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
  ('rto_shipping_waste', 1, 'RTO shipping waste', 'economics', 'EGP', 'modelled', '(outbound leg + return leg) on reversed orders that had dispatched', NULL, NULL, '["week","drop","governorate","courier_zone"]', 'lower_better', 'drop_day', NULL, '["fact_reversal","fact_order","dim_geo"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
  ('contribution_margin', 1, 'Contribution margin', 'economics', 'EGP', 'modelled', 'gross_profit − ad_spend − fulfilment_cost_outbound − cod_collection_fees − rto_shipping_waste', NULL, NULL, '["week","drop","offer"]', 'higher_better', 'drop_day', 'Modelled while any component is modelled (freight, COD fees). The objective function (§0): delivered contribution margin per drop.', '["fact_order","fact_order_line","dim_variant","fact_ad_daily","fact_reversal","dim_geo"]', '1970-01-01', NULL, 'v1: Growth OS L0 seed (GROWTH-OS-SESSION-1-SPEC.md).', '2026-09-12T00:00:00Z'),
